// docs/FEATURES.md is generated by scripts/gen-features-doc.js from the feature
// manifests and the catalogue. A manifest with no catalogue entry has no doc
// line, so this fails; so does a docs/FEATURES.md that was not regenerated.
import { describe, it, expect } from 'vitest';
const fs = require('fs');
const path = require('path');
const { build } = require('../../scripts/gen-features-doc.js');

describe('docs/FEATURES.md', () => {
  const built = build();

  it('has a line for every feature manifest', () => {
    expect(built.missing).toEqual([]);
    for (const m of built.manifests) expect(built.text, m.id).toContain('(`' + m.id + '`)');
    expect(built.total).toBe(built.manifests.length);
  });

  it('is the file the generator would write now', () => {
    const have = fs.readFileSync(path.join(__dirname, '../../docs/FEATURES.md'), 'utf8').replace(/\r\n/g, '\n');
    expect(have).toBe(built.text);
  });

  it('says how to open or turn on every feature and has no emoji', () => {
    expect(built.text).not.toMatch(/\p{Extended_Pictographic}/u);
    const blocks = built.text.split('\n- **').slice(1);
    expect(blocks.length).toBe(built.manifests.length);
    for (const b of blocks) expect(b, b.slice(0, 40)).toMatch(/\n {2}- Open: /);
  });

  it('fails loudly for a manifest nobody describes', () => {
    const { VexFeatures } = require('../../src/renderer/js/feature-catalog.js');
    const without = { ...VexFeatures, ITEMS: VexFeatures.ITEMS.filter(f => f.feature !== 'close-day' && f.id !== 'close-day') };
    expect(without.ITEMS.length).toBe(VexFeatures.ITEMS.length - 1);
    expect(() => build({ catalog: without })).toThrow(/close-day/);
  });
});
